(* [comment removed for export] *)
Definition wa_part_exit (ra sp gp tp t0 t1 t2 s0 s1 a0 a3 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (DW : Z) : machine_state -> Prop :=
  fun ms' => exists (a1' a2' a4' a5' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1' a2' a3 a4' a5' a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0xb71f8) fc None m' (seg_rom asegs)
    /\ munch [(DW, DW + 4)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma wa_part : forall (ra sp gp tp t0 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) F fc (m : mem) (SW DW : Z),
  0 < SW -> SW mod 4 = 0 -> SW + 4 <= 2^47 -> 0 < DW -> DW mod 4 = 0 -> DW + 4 <= 2^47 ->
  (DW + 4 <= 0x7fff7000 \/ 0x10007fff8000 <= DW) ->
  wr_at asegs m SW 4 -> acc asegs m SW 4 -> wr_at asegs m DW 4 -> acc asegs m DW 4 -> mem_inv asegs m ->
  evt asegs (wa_part_exit ra sp gp tp t0 (Z_to_bv 64 2147450880) t2 s0 s1 (Z_to_bv 64 DW) a3 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m DW)
